importScripts('vendor/d3.min.js','vendor/projections.min.js','projection.js');
onmessage=({data:m})=>{try{const {p:src,b:sb}=Atlas.make(m.src),{p:dst,b:db}=Atlas.make(m.dst),w=m.width,h=Math.max(1,Math.round(w*(db[1][1]-db[0][1])/(db[1][0]-db[0][0])));if(w*h>18000000||h>10000)throw Error('出力が大きすぎます。解像度または図法を変更してください。');const out=new Uint8ClampedArray(w*h*4),im=new Uint8ClampedArray(m.pixels),sw=m.sw,sh=m.sh,c=m.crop;let visible=false;const stream=src.stream({point(){visible=true},lineStart(){},lineEnd(){},polygonStart(){},polygonEnd(){}});let targetVisible=false;const targetStream=dst.stream({point(){targetVisible=true},lineStart(){},lineEnd(){},polygonStart(){},polygonEnd(){}});const dx=(db[1][0]-db[0][0])/w,dy=(db[1][1]-db[0][1])/h;for(let y=0;y<h;y++){for(let x=0;x<w;x++){let px=db[0][0]+(x+.5)*dx,py=db[0][1]+(y+.5)*dy,ll=dst.invert([px,py]);if(!ll||!ll.every(Number.isFinite)||Math.abs(ll[1])>90.00001)continue;targetVisible=false;targetStream.point(...ll);if(!targetVisible)continue;let q=dst(ll);if(!q||Math.abs(q[0]-px)>dx*.7||Math.abs(q[1]-py)>dy*.7)continue;visible=false;stream.point(...ll);if(!visible)continue;let sp=src(ll),u=(sp[0]-sb[0][0])/(sb[1][0]-sb[0][0]),v=(sp[1]-sb[0][1])/(sb[1][1]-sb[0][1]);if(u<0||u>1||v<0||v>1)continue;let sx=c.x+u*c.w-.5,sy=c.y+v*c.h-.5,ix=Math.max(c.x,Math.min(c.x+c.w-1,Math.floor(sx))),iy=Math.max(c.y,Math.min(c.y+c.h-1,Math.floor(sy))),o=(y*w+x)*4;if(m.nearest){let j=(Math.min(sh-1,Math.max(0,Math.round(sy)))*sw+Math.min(sw-1,Math.max(0,Math.round(sx))))*4;out.set(im.subarray(j,j+4),o);}else{let fx=Math.max(0,sx-ix),fy=Math.max(0,sy-iy),alpha=0,vals=[0,0,0];for(let a=0;a<2;a++)for(let b=0;b<2;b++){let j=(Math.min(iy+b,c.y+c.h-1)*sw+Math.min(ix+a,c.x+c.w-1))*4,weight=(a?fx:1-fx)*(b?fy:1-fy)*im[j+3]/255;alpha+=weight;for(let k=0;k<3;k++)vals[k]+=im[j+k]*weight;}if(alpha){for(let k=0;k<3;k++)out[o+k]=vals[k]/alpha;out[o+3]=alpha*255;}}}if(y%24===0)postMessage({progress:y/h});}postMessage({done:true,w,h,pixels:out.buffer},[out.buffer]);}catch(e){postMessage({error:e.message})}};
